intentos.respuesta_cruda:
{
  "sql": "SELECT COUNT(*) AS num_vendedores, SUM(ingresos) AS ingresos_totales FROM ( SELECT seller_id, SUM(price) AS ingresos, AVG(review_score_promedio) AS calificación, SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(order_id) AS pct_entregas_tardías FROM vw_ventas_pedido WHERE seller_id IN ( SELECT seller_id FROM vw_ventas_pedido GROUP BY seller_id HAVING COUNT(DISTINCT order_id) >= 30 ) GROUP BY seller_id HAVING ( ingresos > ( SELECT PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY ingresos) FROM ( SELECT seller_id, SUM(price) AS ingresos FROM vw_ventas_pedido WHERE seller_id IN ( SELECT seller_id FROM vw_ventas_pedido GROUP BY seller_id HAVING COUNT(DISTINCT order_id) >= 30 ) GROUP BY seller_id ) ) AND ( calificación < 3.5 OR pct_entregas_tardías > 15 ) )"
}
